///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_confirm",
        method: "post",
        action: "/register/register.do?method=updateIntegUsrIdApplView",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf55300.tx_fn_confirm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.confirm = async function () {
    /* sdd-asis-lifecycle:begin fn_confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = (document.searchForm || { elements: [] });
    scwin.form_searchForm.action = "/register/register.do?method=updateIntegUsrIdApplView";
    scwin.form_searchForm.target = "_self";
    await scwin.tx_fn_confirm();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.logout
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.logout = async function () {
    /* sdd-asis-lifecycle:begin fn_logout — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/logout.do?method=logout). 전환 대상 화면이 확정되면 연결됩니다.');
    /* sdd-asis-lifecycle:end */
};
